void startTask(std::function<std::string()>fn,bool stoppable=false){if(app.busy.exchange(true))return;try{app.control=std::make_shared<Control>();taskControls(true,stoppable);setStatus("正在處理，請稍候…");app.worker=std::thread([fn=std::move(fn)]{CoInitializeEx(nullptr,COINIT_APARTMENTTHREADED);auto r=new Result;try{r->message=fn();}catch(const Cancelled&e){r->message=e.what();}catch(const Error&e){r->message=e.what();r->error=true;}catch(...){r->message="操作尚未完成，已保存的內容仍會保留。請檢查保存位置或重新連接 LINE。";r->error=true;}CoUninitialize();if(!PostMessageW(app.window,MSG_DONE,0,reinterpret_cast<LPARAM>(r)))delete r;});}catch(...){app.busy=false;taskControls(false);throw;}}
