void browse(){if(app.busy)return;IFileDialog*dialog=nullptr;if(FAILED(CoCreateInstance(CLSID_FileOpenDialog,nullptr,CLSCTX_INPROC_SERVER,IID_IFileDialog,reinterpret_cast<void**>(&dialog))))throw Error("無法開啟資料夾選擇畫面。");DWORD options=0;dialog->GetOptions(&options);dialog->SetOptions(options|FOS_PICKFOLDERS|FOS_FORCEFILESYSTEM|FOS_NOCHANGEDIR);dialog->SetTitle(L"選擇你的私人收藏資料夾");if(SUCCEEDED(dialog->Show(app.window))){IShellItem*item=nullptr;if(SUCCEEDED(dialog->GetResult(&item))){PWSTR path=nullptr;if(SUCCEEDED(item->GetDisplayName(SIGDN_FILESYSPATH,&path))){SetWindowTextW(app.folder,path);atomicText(app.config/L"preferences.local.json",safeJson({{"last_archive",narrow(path)}}));CoTaskMemFree(path);}item->Release();}}dialog->Release();}
