void drawChats(){app.drawing=true;ListView_DeleteAllItems(app.list);app.shown=J::array();auto query=narrow(getText(app.search));for(auto&c:app.chats){auto name=c["title"].get<std::string>();if(!query.empty()&&name.find(query)==std::string::npos)continue;app.shown.push_back(c);std::wstring title=wide(name);LVITEMW item{};item.mask=LVIF_TEXT;item.iItem=ListView_GetItemCount(app.list);item.pszText=title.data();int row=ListView_InsertItem(app.list,&item);auto kind=c.value("kind","group");auto type=kind=="direct"?L"個人對話":kind=="community"?L"社群":kind=="subchat"?L"社群聊天室":L"群組";ListView_SetItemText(app.list,row,1,const_cast<wchar_t*>(type));ListView_SetCheckState(app.list,row,app.checked.count(c["source_id"].get<std::string>())?TRUE:FALSE);}app.drawing=false;}
void clearConnection(){app.source.reset();app.chats=J::array();app.checked.clear();drawChats();}
std::string dateRange(int id,bool following){SYSTEMTIME st{};if(SendMessageW(GetDlgItem(app.window,id),DTM_GETSYSTEMTIME,0,reinterpret_cast<LPARAM>(&st))!=GDT_VALID)return "";if(following){FILETIME ft{};SYSTEMTIME midnight{};midnight.wYear=st.wYear;midnight.wMonth=st.wMonth;midnight.wDay=st.wDay;if(!SystemTimeToFileTime(&midnight,&ft))throw Error("日期範圍不正確。");ULARGE_INTEGER value{};value.LowPart=ft.dwLowDateTime;value.HighPart=ft.dwHighDateTime;value.QuadPart+=864000000000ULL;ft.dwLowDateTime=value.LowPart;ft.dwHighDateTime=value.HighPart;FileTimeToSystemTime(&ft,&st);}char out[40];std::snprintf(out,sizeof out,"%04u-%02u-%02uT00:00:00+08:00",st.wYear,st.wMonth,st.wDay);return normalizeTime(out);}
void collectClicked(){if(app.busy)return;if(!app.source)throw Error("請先連接 LINE，或查看人工範例。");J selected=J::array();for(auto&c:app.chats)if(app.checked.count(c["source_id"].get<std::string>()))selected.push_back(c);if(selected.empty())throw Error("請先勾選要整理的聊天室。");std::set<std::string>kinds;for(auto[id,values]:std::vector<std::pair<int,std::set<std::string>>>{{ID_MESSAGES,{"message","thread"}},{ID_ALBUMS,{"album","album_item"}},{ID_NOTES,{"note","comment"}}})if(SendMessageW(GetDlgItem(app.window,id),BM_GETCHECK,0,0)==BST_CHECKED)kinds.insert(values.begin(),values.end());if(kinds.empty())throw Error("請至少選擇一種要整理的內容。");auto since=dateRange(ID_FROM,false),until=dateRange(ID_UNTIL,true);if(!since.empty()&&!until.empty()&&since>=until)throw Error("開始日期不能晚於結束日期。");auto root=folderPath();auto source=app.source;startTask([root,selected,kinds,since,until,source]{Store s(root);J result;try{result=collect(s,*source,selected,*app.control,kinds,since,until,postStatus);}catch(const Cancelled&){exportHtml(s);throw;}catch(...){try{exportHtml(s);}catch(...){}throw;}postStatus("正在產生知識地圖…");auto page=exportHtml(s,[&]{app.control->check();});openPage(page);return "已整理 "+std::to_string(result["items"].get<int>())+" 則內容，沿用 "+std::to_string(result["reused"].get<int>())+" 份附件，新增 "+std::to_string(result["downloaded"].get<int>())+" 份。"+(result["failed"].get<int>()+result["unavailable"].get<int>()>0?" 另有 "+std::to_string(result["failed"].get<int>()+result["unavailable"].get<int>())+" 份附件未能保存，請在地圖查看原因。":"");},true);}
